// Hipoteza generacyjna to obserwacja empiryczna, ze WIEKSZOSC obiektow tworzonych w Javie
// umiera BARDZO MLODO - zmienne lokalne, obiekty tymczasowe (np. StringBuilder w petli)
// zyja zaledwie milisekundy, po czym staja sie smieciem. Skoro wiekszosc smieci powstaje
// wsrod NAJMLODSZYCH obiektow, oplaca sie czesto (i tanio) sprzatac TYLKO maly obszar
// pamieci przeznaczony na 'mlode' obiekty, zamiast za kazdym razem przeszukiwac CALA
// sterte. Dlatego wiekszosc kolektorow dzieli sterte na 'mloda generacje' (czesto
// sprzatana, szybko) i 'stara generacje' (rzadziej sprzatana, wolniej, bo wieksza).

// 1. Zmienne lokalne i parametry na stosie AKTYWNEGO watku - np. `Object o = new Object();`
//    wewnatrz metody main().
// 2. Statyczne pola klas - np. `private static Object cache = new Object();`
// 3. Aktywne watki same w sobie - np. `Thread t = new Thread(runnable); t.start();`
// 4. Referencje JNI - kod natywny (C/C++) trzymajacy obiekt Javy, np. przez JNI GetObjectRef.

Object o = new Object();
System.out.println("osiagalny");
o = null;
System.out.println("nieosiagalny - kandydat do GC");

// MARK: GC przechodzi graf referencji od GC roots i oznacza kazdy napotkany, osiagalny
// obiekt jako 'zywy'.
// SWEEP: GC przechodzi cala sterte i odzyskuje pamiec zajeta przez obiekty NIEoznaczone
// (martwe), zwalniajac ja do ponownej alokacji.
// COMPACT: GC przesuwa pozostale zywe obiekty, zeby byly obok siebie (bez dziur),
// eliminujac fragmentacje pamieci i przyspieszajac kolejne alokacje.

// Minor GC sprzata TYLKO mloda generacje (Eden+Survivor) - szybkie i czeste. Major GC
// sprzata stara generacje - obiekty, ktore przetrwaly kilka cykli minor GC i zostaly
// 'awansowane'. Full GC sprzata CALA sterte (mloda+stara+czesto Metaspace) - jest
// NAJWOLNIEJSZY, bo musi przeanalizowac i ewentualnie skompaktowac cala dostepna pamiec,
// zamiast tylko malego, dedykowanego obszaru mlodej generacji.

for (GarbageCollectorMXBean gcBean : ManagementFactory.getGarbageCollectorMXBeans()) {
    System.out.println(gcBean.getName());
}

for (GarbageCollectorMXBean gcBean : ManagementFactory.getGarbageCollectorMXBeans()) {
    System.out.println(gcBean.getName() + ": count=" + gcBean.getCollectionCount() + ", time=" + gcBean.getCollectionTime() + " ms");
}

for (int i = 0; i < 10_000; i++) {
    byte[] junk = new byte[16];
}
System.out.println("gotowe");

long total = ManagementFactory.getGarbageCollectorMXBeans().stream()
    .mapToLong(GarbageCollectorMXBean::getCollectionCount)
    .sum();
System.out.println("Laczna liczba cykli GC: " + total);

// Pole statyczne klasy jest GC rootem, bo NALEZY do samej klasy (nie do instancji obiektu) -
// dopoki klasa jest zaladowana w JVM, JVM traktuje jej statyczne pola jako punkt startowy
// analizy osiagalnosci, niezaleznie od tego, czy ktokolwiek trzyma referencje do jakiejkolwiek
// instancji tej klasy. Obiekt przypisany do pola statycznego pozostaje wiec osiagalny
// (i odporny na GC) tak dlugo, jak dana klasa pozostaje zaladowana przez swoj ClassLoader -
// co w typowej aplikacji oznacza CALY czas dzialania programu, chyba ze pole zostanie
// jawnie wyzerowane (ustawione na null).

long before = ManagementFactory.getGarbageCollectorMXBeans().stream().mapToLong(GarbageCollectorMXBean::getCollectionCount).sum();
for (int i = 0; i < 100_000; i++) { byte[] junk = new byte[32]; }
long after = ManagementFactory.getGarbageCollectorMXBeans().stream().mapToLong(GarbageCollectorMXBean::getCollectionCount).sum();
System.out.println("Przed: " + before + ", po: " + after + ", wzrost: " + (after > before));

record Node(Node next, String label) { }

Node n5 = new Node(null, "5");
Node n4 = new Node(n5, "4");
Node n3 = new Node(n4, "3");
Node n2 = new Node(n3, "2");
Node n1 = new Node(n2, "1");
// Zmienna lokalna n1 (GC root - lokalna zmienna na stosie watku) trzyma referencje do n2,
// ktora trzyma referencje do n3, itd. - caly lancuch 5 wezlow jest osiagalny WYLACZNIE
// dzieki temu, ze n1 (i tylko n1) jest bezposrednio referencjonowany z GC roota.

class MutableNode {
    MutableNode next;
    String label;
    MutableNode(MutableNode next, String label) { this.next = next; this.label = label; }
}

MutableNode n5 = new MutableNode(null, "5");
MutableNode n4 = new MutableNode(n5, "4");
MutableNode n3 = new MutableNode(n4, "3");
MutableNode n2 = new MutableNode(n3, "2");
MutableNode n1 = new MutableNode(n2, "1");
n1.next = null; // odpinamy n2 (i posrednio n3, n4, n5)
// Po n1.next = null, n2 (a wiec i n3, n4, n5, bo byly osiagalne WYLACZNIE przez n2)
// staja sie NIEOSIAGALNE - zaden GC root juz do nich nie prowadzi, mimo ze wciaz
// istnieja wzajemne referencje MIEDZY n2->n3->n4->n5.

for (int iter = 0; iter < 3; iter++) {
    for (int i = 0; i < 200_000; i++) { byte[] junk = new byte[32]; }
    long totalTime = ManagementFactory.getGarbageCollectorMXBeans().stream().mapToLong(GarbageCollectorMXBean::getCollectionTime).sum();
    System.out.println("Iteracja " + iter + ": laczny czas GC = " + totalTime + " ms");
}
// Oczekiwany trend: suma czasu GC ROSNIE (lub pozostaje stabilna) z kazda iteracja,
// nigdy nie maleje - to LICZNIK NARASTAJACY od startu JVM, nie 'chwilowy' pomiar.

// Awansowanie (promotion) to przeniesienie obiektu z mlodej generacji do starej, gdy
// obiekt PRZETRWA wystarczajaco duzo cykli minor GC (typowy prog to kilka-kilkanascie
// cykli, konfigurowalny). Nie dzieje sie od razu, bo zgodnie z hipoteza generacyjna
// WIEKSZOSC obiektow umiera mlodo - gdyby kazdy obiekt byl awansowany po JEDNYM
// przetrwanym cyklu, stara generacja szybko wypelnilaby sie obiektami, ktore i tak
// wkrotce staly sie smieciem. Wymaganie kilku przetrwan filtruje obiekty PRAWDZIWIE
// dlugozyjace (np. cache, singletony) od tych, ktore tylko przypadkowo przezyly jeden
// cykl minor GC z powodu momentu jego wywolania.

List<GarbageCollectorMXBean> beans = ManagementFactory.getGarbageCollectorMXBeans();
for (GarbageCollectorMXBean b : beans) {
    System.out.println(b.getName() + ": " + b.getCollectionCount());
}
for (int i = 0; i < 300_000; i++) { byte[] junk = new byte[32]; }
for (GarbageCollectorMXBean b : beans) {
    System.out.println(b.getName() + " (po): " + b.getCollectionCount());
}
// Typowo dla G1: kolektor 'mlody' (np. 'G1 Young Generation') rosnie CZESCIEJ niz kolektor
// 'stary/mieszany' (np. 'G1 Concurrent GC' lub 'G1 Old Generation'), zgodnie z hipoteza
// generacyjna - wiekszosc alokacji jest sprzatana szybko w mlodej generacji.

CountDownLatch latch = new CountDownLatch(1);
NotificationListener listener = (notification, handback) -> {
    System.out.println("Zdarzenie GC odebrane");
    latch.countDown();
};
for (GarbageCollectorMXBean gcBean : ManagementFactory.getGarbageCollectorMXBeans()) {
    if (gcBean instanceof NotificationEmitter emitter) {
        emitter.addNotificationListener(listener, null, null);
    }
}
for (int i = 0; i < 150_000; i++) { byte[] junk = new byte[32]; }
System.gc();
boolean received = latch.await(3, TimeUnit.SECONDS);
System.out.println("Odebrano: " + received);

// Pauza 'stop-the-world' to moment, w ktorym GC ZATRZYMUJE WSZYSTKIE watki aplikacji
// (poza samym GC), zeby bezpiecznie przeanalizowac/przesunac obiekty na stercie bez
// ryzyka, ze aplikacja w tym samym czasie zmieni graf referencji. Dla wiekszosci aplikacji
// kilkumilisekundowa pauza jest niezauwazalna, ale dla systemow czasu rzeczywistego (np.
// tradingowych, gdzie liczy sie kazda milisekunda przewagi, albo gier, gdzie dluzsza pauza
// oznacza WIDOCZNE 'zacinanie sie' obrazu) nawet krotkie zatrzymanie CALEJ aplikacji moze
// oznaczac przegrana transakcje lub zauwazalny spadek plynnosci - dlatego takie systemy
// czesto wybieraja kolektory nisko-pauzowe (ZGC/Shenandoah - patrz Lesson11).

static String gcSnapshot() {
    StringBuilder sb = new StringBuilder();
    for (GarbageCollectorMXBean b : ManagementFactory.getGarbageCollectorMXBeans()) {
        sb.append(b.getName()).append(": count=").append(b.getCollectionCount())
          .append(", time=").append(b.getCollectionTime()).append(" ms\n");
    }
    return sb.toString();
}

System.out.println(gcSnapshot());

long beforeKept = ManagementFactory.getGarbageCollectorMXBeans().stream().mapToLong(GarbageCollectorMXBean::getCollectionCount).sum();
List<byte[]> kept = new ArrayList<>();
for (int i = 0; i < 500_000; i++) kept.add(new byte[16]);
long afterKept = ManagementFactory.getGarbageCollectorMXBeans().stream().mapToLong(GarbageCollectorMXBean::getCollectionCount).sum();

long beforeDiscarded = afterKept;
for (int i = 0; i < 500_000; i++) { byte[] junk = new byte[16]; }
long afterDiscarded = ManagementFactory.getGarbageCollectorMXBeans().stream().mapToLong(GarbageCollectorMXBean::getCollectionCount).sum();

System.out.println("Trzymane (osiagalne): wzrost licznika=" + (afterKept - beforeKept));
System.out.println("Porzucone (nieosiagalne): wzrost licznika=" + (afterDiscarded - beforeDiscarded));
// Obiekty TRZYMANE w liscie NIE moga zostac odzyskane przez GC (sa osiagalne), wiec
// alokacja zajmuje coraz wiecej pamieci bez zwalniania - moze to wywolac WIECEJ cykli GC
// (lub wieksze/dluzsze), bo GC probuje znalezc miejsce, ale nie moze nic odzyskac z tej listy.

class TreeNode {
    String label;
    List<TreeNode> children = new ArrayList<>();
    TreeNode(String label) { this.label = label; }
}

TreeNode root = new TreeNode("root");
TreeNode left = new TreeNode("left");
TreeNode right = new TreeNode("right");
root.children.add(left);
root.children.add(right);
for (int i = 0; i < 4; i++) left.children.add(new TreeNode("left-child-" + i));
for (int i = 0; i < 4; i++) right.children.add(new TreeNode("right-child-" + i));

root.children.remove(right); // odcinamy cala galaz 'right' (5 wezlow: right + 4 dzieci)
// Po odcieciu, 'root' i 'left' oraz jej 4 dzieci pozostaja OSIAGALNE (6 wezlow razem) -
// 'right' i jej 4 dzieci staja sie NIEOSIAGALNE (zaden GC root juz do nich nie prowadzi).

long before1 = totalGcCount();
for (int i = 0; i < 100_000; i++) { byte[] small = new byte[16]; }
long after1 = totalGcCount();

long before2 = totalGcCount();
for (int i = 0; i < 10_000; i++) { byte[] big = new byte[8192]; }
long after2 = totalGcCount();

System.out.println("Male obiekty: wzrost=" + (after1 - before1));
System.out.println("Duze obiekty: wzrost=" + (after2 - before2));
// Wieksze pojedyncze alokacje moga czesciej wymuszac cykl GC (mniej 'miejsca' zostaje w
// mlodej generacji po kazdej), nawet przy mniejszej LICZBIE obiektow - liczba I rozmiar
// alokacji WPLYWAJA NIEZALEZNIE na czestotliwosc GC.

static long totalGcCount() {
    return ManagementFactory.getGarbageCollectorMXBeans().stream().mapToLong(GarbageCollectorMXBean::getCollectionCount).sum();
}

List<String> events = Collections.synchronizedList(new ArrayList<>());
NotificationListener listener = (notification, handback) -> {
    if (GarbageCollectionNotificationInfo.GARBAGE_COLLECTION_NOTIFICATION.equals(notification.getType())) {
        GarbageCollectionNotificationInfo info = GarbageCollectionNotificationInfo.from((CompositeData) notification.getUserData());
        events.add(info.getGcName() + " / " + info.getGcCause() + " / " + info.getGcInfo().getDuration() + "ms");
    }
};
for (GarbageCollectorMXBean b : ManagementFactory.getGarbageCollectorMXBeans()) {
    if (b instanceof NotificationEmitter emitter) emitter.addNotificationListener(listener, null, null);
}
for (int i = 0; i < 150_000; i++) { byte[] junk = new byte[32]; }
System.gc();
Thread.sleep(3000);
System.out.println(events.isEmpty() ? "Brak zebranych zdarzen w 3s" : "Zebrane zdarzenia: " + events);

static List<byte[]> leak = new ArrayList<>();

for (int i = 0; i < 50_000; i++) {
    leak.add(new byte[64]);
}
System.out.println("Rozmiar listy: " + leak.size());
// Statyczne pole 'leak' jest GC rootem (patrz Zadanie 10) - dopoki klasa jest zaladowana,
// KAZDY element listy jest osiagalny przez lancuch: statyczne pole -> lista -> element.
// GC nie usuwa obiektow, ktore SA osiagalne - to nie jest 'blad' GC, tylko normalne
// dzialanie zgodnie z definicja: GC sprzata WYLACZNIE to, do czego NIE MA zadnej sciezki
// od GC roota. Klasyczny 'memory leak' w Javie to WLASNIE takie NIEZAMIERZONE trzymanie
// referencji przez dlugozyjacy obiekt (tu: statyczne pole), zapobiegajace GC.

long beforeA = totalGcCount();
for (int i = 0; i < 200_000; i++) { byte[] junk = new byte[32]; }
long afterA = totalGcCount();

List<byte[]> kept = new ArrayList<>();
long beforeB = afterA;
for (int i = 0; i < 200_000; i++) {
    byte[] item = new byte[32];
    if (i % 10 == 0) kept.add(item);
}
long afterB = totalGcCount();

System.out.println("Wariant (a) wszystko odrzucone: wzrost=" + (afterA - beforeA));
System.out.println("Wariant (b) 10% trzymane: wzrost=" + (afterB - beforeB) + ", trzymanych=" + kept.size());

// Przykladowa klasa UserDao z _10_dao typowo zawiera:
// - statyczne pole `private static final DataSource DATA_SOURCE = ...;` - to GC ROOT typu
//   'statyczne pole klasy' - trzyma DataSource osiagalny przez caly czas zycia aplikacji.
// - w metodzie `findById(long id)` lokalna zmienna `Connection conn = dataSource.getConnection();`
//   - to GC ROOT typu 'zmienna lokalna na stosie aktywnego watku', osiagalna TYLKO podczas
//   wykonywania tej konkretnej metody, na TYM konkretnym watku.
// - jesli DAO uruchamia asynchroniczne zapytania na osobnym watku (np. `new Thread(() -> ...)`),
//   sam obiekt Thread jest GC rootem typu 'aktywny watek', dopoki watek dziala.

List<Long> waitTimesMs = new ArrayList<>();
for (int trial = 0; trial < 5; trial++) {
    CountDownLatch latch = new CountDownLatch(1);
    NotificationListener listener = (n, h) -> latch.countDown();
    for (GarbageCollectorMXBean b : ManagementFactory.getGarbageCollectorMXBeans()) {
        if (b instanceof NotificationEmitter emitter) emitter.addNotificationListener(listener, null, null);
    }
    long start = System.nanoTime();
    for (int i = 0; i < 150_000; i++) { byte[] junk = new byte[32]; }
    System.gc();
    boolean received = latch.await(3, TimeUnit.SECONDS);
    long elapsedMs = (System.nanoTime() - start) / 1_000_000;
    if (received) waitTimesMs.add(elapsedMs); else System.out.println("Proba " + trial + ": brak powiadomienia");
}
if (!waitTimesMs.isEmpty()) {
    double avg = waitTimesMs.stream().mapToLong(Long::longValue).average().orElse(0);
    long max = waitTimesMs.stream().mapToLong(Long::longValue).max().orElse(0);
    System.out.println("Srednia: " + avg + " ms, max: " + max + " ms");
}

// Raport: Czeste Full GC na produkcji jest sygnalem ostrzegawczym, poniewaz Full GC
// przeszukuje CALA sterte (nie tylko mloda generacje) i wymaga najdluzszej pauzy
// stop-the-world sposrod wszystkich typow GC - podczas niej WSZYSTKIE watki aplikacji sa
// zatrzymane, wiec uzytkownicy doswiadczaja zauwazalnych opoznien lub timeoutow. Czesty
// Full GC zazwyczaj oznacza, ze stara generacja szybko sie zapelnia - typowe przyczyny to
// wyciek pamieci (obiekty NIGDY nie staja sie nieosiagalne, patrz Zadanie 24), zbyt maly
// rozmiar sterty (-Xmx) wzgledem realnych potrzeb aplikacji, lub zbyt agresywne
//'awansowanie' obiektow do starej generacji. Warto monitorowac: (1) laczna liczbe cykli
// Full GC w czasie (getCollectionCount() per kolektor 'stary'), (2) laczny czas spedzony
// w GC wzgledem calkowitego czasu dzialania aplikacji (getCollectionTime() jako procent
// uptime) oraz (3) trend zuzycia starej generacji w czasie (rosnie liniowo bez spadkow =
// mozliwy wyciek pamieci).

class CacheEntry {
    byte[] data;
    int ageTicks = 0;
    CacheEntry(byte[] data) { this.data = data; }
}

Map<String, CacheEntry> cache = new HashMap<>();
cache.put("a", new CacheEntry(new byte[1024]));
cache.put("b", new CacheEntry(new byte[1024]));
cache.values().forEach(e -> e.ageTicks++);

void evictUnreachable(Map<String, CacheEntry> cache, int maxAge) {
    cache.entrySet().removeIf(e -> e.getValue().ageTicks > maxAge);
}
// To podejscie jest SYMULACJA opartaB NA JAWNYM LICZNIKU CZASU, calkowicie ROZNA od
// prawdziwego GC - prawdziwy GC decyduje na podstawie OSIAGALNOSCI (czy istnieje sciezka
// referencji od GC roota), a nie 'wieku' - obiekt moze byc bardzo 'stary', a wciaz
// osiagalny (i GC go NIE usunie), albo bardzo 'mlody', a juz calkowicie nieosiagalny
// (i GC MOZE go usunac przy najblizszej okazji).

System.out.println("=== RAPORT: PODSTAWY GARBAGE COLLECTION ===");

System.out.println("--- Kolektory PRZED alokacja ---");
for (GarbageCollectorMXBean b : ManagementFactory.getGarbageCollectorMXBeans()) {
    System.out.println(b.getName() + ": count=" + b.getCollectionCount() + ", time=" + b.getCollectionTime() + "ms");
}

CountDownLatch latch = new CountDownLatch(1);
NotificationListener listener = (n, h) -> latch.countDown();
for (GarbageCollectorMXBean b : ManagementFactory.getGarbageCollectorMXBeans()) {
    if (b instanceof NotificationEmitter emitter) emitter.addNotificationListener(listener, null, null);
}

for (int i = 0; i < 300_000; i++) { byte[] junk = new byte[32]; }
System.gc();
boolean received = latch.await(3, TimeUnit.SECONDS);

System.out.println("--- Kolektory PO alokacji ---");
for (GarbageCollectorMXBean b : ManagementFactory.getGarbageCollectorMXBeans()) {
    System.out.println(b.getName() + ": count=" + b.getCollectionCount() + ", time=" + b.getCollectionTime() + "ms");
}

System.out.println("--- Powiadomienie GC ---");
System.out.println("Odebrano: " + received);
